\usepackage{tikz}
\usetikzlibrary{shapes.geometric}

\newcommand{\square}[1]{%
  \node[draw, rectangle, minimum size=1cm] at (#1) {};
}

\begin{document}

\begin{tikzpicture}[x=1cm,y=1cm]
  \foreach \i in {0,...,7} {
